insert into products (id, niche_id, seller_id, slug, category, art, color, name_ar, lead_ar, price, attributes, variants, status, views, reviews, faq, images, en, profile)
values ('bonds-chrome', 'coffee', 'bonds', 'bonds-chrome', 'blends', 'coffee', '#7C8B5A', 'قهوة كروم بلند', 'بلند بقوام غني وممتلئ وحموضة خفيفة: كراميل، شوكولاتة داكنة ومكسرات محمصة. حلوة سادة أو باللبن.', 225, '{"النكهات":"كراميل، شوكولاتة داكنة، مكسرات محمصة","القوام":"غني وممتلئ","الحموضة":"خفيفة","النوع":"بلند","الشكل":"حبوب أو مطحونة على طلبك"}'::jsonb, '[{"label":"250 جم","labelEn":"250 g","stock":20,"price":225,"opts":{"weight":"250 جم"}},{"label":"1 كجم","labelEn":"1 kg","stock":20,"price":900,"opts":{"weight":"1 كجم"}}]'::jsonb, 'live', 0, '[]'::jsonb, '[["مين بيحمص القهوة؟","بوندز لتحميص القهوة، شريكنا. القهوة جاية من المحمصة على طول، أصلية ومقفولة."],["حبوب ولا مطحونة؟","زي ما تحب: اختار طريقة التحضير وإحنا نطحنها بعد طلبك، من ناعم جداً للكنكة لخشن للفرنش بريس. ولو عندك مطحنة اختار حبوب كاملة."],["أحفظها إزاي؟","في الكيس مقفول، في مكان ناشف بعيد عن الشمس والتلاجة. أحلى طعم خلال 4 أسابيع من الفتح."]]'::jsonb, '["/products/coffee/chrome.webp"]'::jsonb, '{"name":"Chrome Blend","lead":"A blend with a full, rich body and mild acidity: caramel, dark chocolate and roasted nuts. Great black or with milk.","attributes":{"Tasting notes":"Caramel, dark chocolate, roasted nuts","Body":"Full and rich","Acidity":"Mild","Type":"Blend","Form":"Whole beans or ground to order"},"faq":[["Who roasts the coffee?","Bonds Coffee Roasters, our partner. The coffee comes straight from the roastery, original and sealed."],["Beans or ground?","Your choice: pick how you brew and we grind it after you order, from extra fine for the kanaka to coarse for a French press. Have a grinder? Choose whole beans."],["How do I store it?","In the closed bag, somewhere dry, away from sunlight and the fridge. Best within 4 weeks of opening."]]}'::jsonb, '{"notes":["كراميل","شوكولاتة داكنة","مكسرات محمصة"],"notesEn":["Caramel","Dark chocolate","Roasted nuts"],"family":"chocolate","scales":{"body":5,"acidity":2}}'::jsonb)
