insert into products (id, niche_id, seller_id, slug, category, art, color, name_ar, lead_ar, price, attributes, variants, status, views, reviews, faq, images, en, profile)
values ('bonds-ethiopia-limu', 'coffee', 'bonds', 'bonds-ethiopia-limu', 'single-origin', 'coffee', '#9A5B34', 'إثيوبيا ليمو', 'قهوة أحادية المصدر من ليمو في إثيوبيا، معالجة طبيعية: شوكولاتة داكنة، شاي أسود، سكر بني ولمسة برتقال.', 300, '{"النكهات":"شوكولاتة داكنة، مكسرات محمصة، شاي أسود، سكر بني، برتقال","المنشأ":"إثيوبيا · ليمو","السلالة":"هيرلوم","المعالجة":"طبيعية","النوع":"أحادية المصدر","الشكل":"حبوب أو مطحونة على طلبك"}'::jsonb, '[{"label":"250 جم","labelEn":"250 g","stock":20,"price":300,"opts":{"weight":"250 جم"}},{"label":"1 كجم","labelEn":"1 kg","stock":20,"price":1200,"opts":{"weight":"1 كجم"}}]'::jsonb, 'live', 0, '[]'::jsonb, '[["مين بيحمص القهوة؟","بوندز لتحميص القهوة، شريكنا. القهوة جاية من المحمصة على طول، أصلية ومقفولة."],["حبوب ولا مطحونة؟","زي ما تحب: اختار طريقة التحضير وإحنا نطحنها بعد طلبك، من ناعم جداً للكنكة لخشن للفرنش بريس. ولو عندك مطحنة اختار حبوب كاملة."],["أحفظها إزاي؟","في الكيس مقفول، في مكان ناشف بعيد عن الشمس والتلاجة. أحلى طعم خلال 4 أسابيع من الفتح."]]'::jsonb, '["/products/coffee/ethiopia-limu.webp","/products/coffee/bonds-shelf.webp"]'::jsonb, '{"name":"Ethiopia Limu","lead":"Single-origin coffee from Limu, Ethiopia, natural process: dark chocolate, black tea, brown sugar and a touch of orange.","attributes":{"Tasting notes":"Dark chocolate, roasted nuts, black tea, brown sugar, orange","Origin":"Ethiopia · Limu","Variety":"Heirloom","Process":"Natural","Type":"Single origin","Form":"Whole beans or ground to order"},"faq":[["Who roasts the coffee?","Bonds Coffee Roasters, our partner. The coffee comes straight from the roastery, original and sealed."],["Beans or ground?","Your choice: pick how you brew and we grind it after you order, from extra fine for the kanaka to coarse for a French press. Have a grinder? Choose whole beans."],["How do I store it?","In the closed bag, somewhere dry, away from sunlight and the fridge. Best within 4 weeks of opening."]]}'::jsonb, '{"notes":["شوكولاتة داكنة","شاي أسود","برتقال"],"notesEn":["Dark chocolate","Black tea","Orange"],"family":"fruity"}'::jsonb)
