opening."]]}'::jsonb, '{"notes":["بندق محمص","قصب السكر","عين جمل"],"notesEn":["Roasted hazelnut","Sugar cane","Walnut"],"family":"chocolate","scales":{"body":4,"acidity":1}}'::jsonb)
