on conflict (id) do update set name_ar = excluded.name_ar, lead_ar = excluded.lead_ar, category = excluded.category, art = excluded.art, color = excluded.color, attributes = excluded.attributes, faq = excluded.faq, en = excluded.en, profile = coalesce(excluded.profile, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object('ribbon', products.profile->'ribbon')), images = excluded.images, status = excluded.status;
-- (A ribbon set in the admin is kept inside "profile" on a re-run.)

-- Prices and stock are managed in the admin (Products) once a coffee exists: a re-run never
-- changes them. It only fills a price where a weight has none, and refreshes option names:
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then ('{"price":225}'::jsonb::jsonb || e) || '{"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then ('{"price":900}'::jsonb::jsonb || e) || '{"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-chrome';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then ('{"price":245}'::jsonb::jsonb || e) || '{"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then ('{"price":980}'::jsonb::jsonb || e) || '{"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-amber';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then ('{"price":500}'::jsonb::jsonb || e) || '{"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then ('{"price":2000}'::jsonb::jsonb || e) || '{"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-ethiopia-guji';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then ('{"price":300}'::jsonb::jsonb || e) || '{"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then ('{"price":1200}'::jsonb::jsonb || e) || '{"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-ethiopia-limu';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then ('{"price":325}'::jsonb::jsonb || e) || '{"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then ('{"price":1300}'::jsonb::jsonb || e) || '{"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-brazil-red-catuai';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then ('{"price":375}'::jsonb::jsonb || e) || '{"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then ('{"price":1500}'::jsonb::jsonb || e) || '{"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-colombia-castillo';
update products set variants = (select jsonb_agg(case when e->>'label' = '250 جم' then ('{"price":450}'::jsonb::jsonb || e) || '{"opts":{"weight":"250 جم"},"labelEn":"250 g"}'::jsonb when e->>'label' = '1 كجم' then ('{"price":1800}'::jsonb::jsonb || e) || '{"opts":{"weight":"1 كجم"},"labelEn":"1 kg"}'::jsonb else e end) from jsonb_array_elements(variants) e) where id = 'bonds-el-salvador';

-- Coffees no longer sold: hidden (kept for past orders).
update products set status = 'hidden' where id in ('bonds-sienna', 'bonds-brazil-cerrado');

commit;

-- To receive Bonds' orders on Telegram: open the bot from the Telegram account that
-- handles Bonds orders, send /myid, then run (with that number):
--   update sellers set telegram_chat_id = 123456789 where id = 'bonds';
